package net.civeira.phylax.feature.observe.observedsource.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class ManagedVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property managed of observed source ")
  void test_managed_v_o_builder() {
    Assertions.assertThrows(ConstraintException.class, () -> ManagedVO.tryFrom(null));
    Assertions.assertEquals(true, ManagedVO.from(true).isManaged());
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class, () -> ManagedVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + true + "]", ManagedVO.from(true).toString());
  }
}
